registerModuleVariants('immob.assistClause', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["","braced by what the room provides","furniture doing quiet work on her behalf","cushions and angles holding the arrangement"] }]);
registerModuleVariants('immob.assistance', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["",", steadied by arrangement"," — held by cushions and angles",", braced and guided by what the room provides"] }]);
registerModuleVariants('immob.bodyDesc', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["vast warm softness","immobile abundance at rest","warmth pooled where gravity directs it","soft mass filling the available space"] }]);
registerModuleVariants('immob.register', [{ when: { stageMin: 0, stageMax: 10 }, weight: 1, text: ["She rests without commentary.","Silence — vast, warm, sufficient.","She breathes around her own immensity.","Stillness suits her at this scale."] }]);
registerModuleVariants('immob.refit', [{ when: { stageMin: 0, stageMax: 7 }, weight: 1, text: ["New numbers. New garments. Everything made for what she actually is now.","She is measured and fitted — fabric in abundance, nothing straining. She receives the new clothes like her due.","Soft fabric arrives sized to her fullness — nothing pinches, nothing pretends she is smaller.","The tailor's work acknowledges her scale without apology. She wears the result like a crown."] }]);
registerModuleVariants('immob.comfort.bed', [{ when: { stageMin: 0, stageMax: 7 }, weight: 1, text: ["The new frame arrives — reinforced, wide, built to hold her. She settles onto it and something in her exhales completely. \"This,\" she says, \"is actually right.\"","The right bed finally. She finds the center without effort, redistributes, stills. The wood doesn't shift under her. \"Better,\" she says.","She sinks into the reinforced frame and goes still — mass accepted, weight held, finally.","The bed does not complain. She notices. She appreciates it aloud."] }]);
registerModuleVariants('immob.comfort.bed', [{ when: { stage: [10] }, weight: 1, text: ["The new frame arrives — reinforced, wide, built to hold her. She settles onto it and something in her exhales completely. \"This,\" she says, \"is actually right.\"","The right bed finally. She finds the center without effort, redistributes, stills. The wood doesn't shift under her. \"Better,\" she says.","She sinks into the reinforced frame and goes still — mass accepted, weight held, finally.","The bed does not complain. She notices. She appreciates it aloud."] }]);
registerModuleVariants('immob.comfort.fan', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["The fan goes on and she closes her eyes into it. Cool air across the warm expanse of her — you watch her simply receive it. \"Leave it running,\" she says.","Moving air against her warmth. She settles differently under it — easier, softer. \"That helps,\" she says. \"That actually helps.\"","The fan finds the places heat pools thickest. She breathes slower. \"Yes,\" she murmurs.","Cool air crosses belly and thigh and the soft landscape between. She does not move to meet it. She lets it come to her."] }]);
registerModuleVariants('immob.comfort.position', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["She shifts a little as you adjust — cushions repositioned, supports moved in. Something finds its place. She goes still. \"There. That's the one.\"","The rearrangement takes two minutes. She settles into it and the tension she'd been holding releases — that small ongoing adjustment, finally done.","Cushions under hip and belly; supports where mass needs them. She tests the new geometry and stops moving.","\"Better,\" she says once. Then silence — the good kind."] }]);
registerModuleVariants('immob.comfort.ac', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["The temperature finds itself for the first time. Her next breath is longer, slower. The heat she carries everywhere finally has somewhere to put itself.","Cool air, properly. She doesn't say anything, but the room is different. She is different in the room — easier, more settled. Less occupied with the warmth.","The climate adjusts to her, not the other way around. She breathes easier immediately.","Cool settles over warm mass like a blessing. She closes her eyes and receives it."] }]);
registerModuleVariants('immob.comfort.arrangement', [{ when: { stageMin: 0, stageMax: 7 }, weight: 1, text: ["Everything within reach. The room edited to her permanence — trays at height, paths cleared, space organized around what she is now. She looks at it, then at you. \"You did this.\"","The room rearranged to fit her rather than the other way around. She surveys it without moving. \"Good,\" she says. \"Finally.\"","Trays, cushions, reach — all calibrated to immobile comfort. She approves with a slow nod.","The space stops fighting her size. She receives the rearrangement like her due."] }]);
registerModuleVariants('immob.comfort.arrangement', [{ when: { stage: [10] }, weight: 1, text: ["Everything within reach. The room edited to her permanence — trays at height, paths cleared, space organized around what she is now. She looks at it, then at you. \"You did this.\"","The room rearranged to fit her rather than the other way around. She surveys it without moving. \"Good,\" she says. \"Finally.\"","Trays, cushions, reach — all calibrated to immobile comfort. She approves with a slow nod.","The space stops fighting her size. She receives the rearrangement like her due."] }]);
registerModuleVariants('immob.hint.heat', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["","","Warmth gathers where she rests — unremarked, for now.","She fans herself once without looking up."] }]);
registerModuleVariants('immob.hint.position', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["","","She shifts once, twice — seeking a geometry her mass will accept.","A small adjustment she does not name aloud."] }]);
registerModuleVariants('immob.hint.food', [{ when: { stageMin: 0, stageMax: 11 }, weight: 1, text: ["","","She eyes the tray with the faintest flicker of preference.","An appetite with opinions she has not voiced yet."] }]);
registerModuleVariants('immob.pref.heat', [{ when: { stageMin: 0, stageMax: 11 }, weight: 1, text: ["","Moving air finds her skin. She exhales once, satisfied.","The fan hums. Court is cooler now.","Cool air crosses the warm expanse of her. She closes her eyes into it."] }]);
registerModuleVariants('immob.pref.position', [{ when: { stageMin: 0, stageMax: 11 }, weight: 1, text: ["","She settles into the new geometry — finally, properly held.","\"There,\" she murmurs. \"That's better.\"","Cushions shift; mass follows. She goes still."] }]);
registerModuleVariants('immob.pref.food', [{ when: { stageMin: 0, stageMax: 11 }, weight: 1, text: ["","She eats without commentary — fast, focused, pleased.","The tray was right. Her appetite knows it.","Preference honored. Hunger answered. Court is calm again."] }]);
registerModuleVariants('immob.visit', [{ when: { stageMin: 0, stageMax: 10 }, weight: 1, text: ["{ref.name} comes to {subject.name} where she rests. They share the afternoon — she brings the outside in; {subject.name} doesn't have to go anywhere for it.","The visit is brief, unhurried. {ref.name} fills the room with outside news, and {subject.name} receives it.","{ref.name} sits within reach. Conversation flows; {subject.name} eats; the afternoon passes warm and unremarkable in the best way.","A visitor, food, gossip — {subject.name} receives court without leaving her settled mass."] }]);
registerModuleVariants('immob.arrival.tend', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["You bring the day to {subject.name} where she rests — the food, the warmth, the company, all of it arriving at her now instead of the other way around.","Court happens where she lies — you ferry trays, news, and touch to the warm center of her mass.","The world comes to her in pieces you carry: meals, blankets, conversation, devotion.","You tend her where she has settled — vast, warm, immobile — and the tending becomes the day's purpose."] }]);
registerModuleVariants('immob.arrival.deepen', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["And she settles deeper as you tend her, softening further into the shape of being kept, every comfort folding another warm degree into her.","Tended, she softens by degrees — mass rearranging, warmth spreading, the pleasure of being held in place.","Each comfort lands and stays; she grows softer under care, not smaller — more settled, more hers.","Being kept agrees with her. She shows it in how still she becomes when you adjust the cushions."] }]);
registerModuleVariants('immob.arrival.devotion', [{ when: { stageMin: 0, stageMax: 9 }, weight: 1, text: ["{subject.name} settles under your care, warm and vast and wholly content to be exactly where she is.","Contentment pools in her expression — vast body, small smile, absolute permission to stay.","She receives your tending like weather she ordered: warm, constant, deserved.","{subject.name} closes her eyes into the care and does not hurry to open them."] }]);
registerModuleVariants('immob.arrival', [{ when: { stageMin: 0, stageMax: 11 }, weight: 1, text: ["{immob.arrival.tend} {immob.arrival.deepen} {immob.arrival.devotion}","{immob.arrival.tend} {immob.arrival.devotion} {immob.arrival.deepen}","{immob.arrival.deepen} {immob.arrival.tend} {immob.arrival.devotion}","{immob.arrival.tend} {immob.arrival.deepen}"] }]);
registerModuleVariants('immob.scene', [{ when: { stageMin: 0, stageMax: 11 }, weight: 1, text: ["{immob.settledState} {immob.environmental} {immob.attempt|prefix: }{immob.assistance|prefix: }{immob.register}","{immob.settledState} {immob.spaceObs} {immob.register}","{immob.environmental} {immob.bodyDesc|prefix:, }{immob.register}","{immob.settledState} {immob.bodyDesc|prefix:, }{immob.spaceObs|prefix: }{immob.register}"] }]);
